package com.example.pryanik.commands;

import com.example.pryanik.*;
import com.sk89q.worldedit.IncompleteRegionException;
import com.sk89q.worldedit.bukkit.BukkitAdapter;
import com.sk89q.worldedit.bukkit.WorldEditPlugin;
import com.sk89q.worldedit.regions.Region;
import com.sk89q.worldguard.WorldGuard;
import com.sk89q.worldguard.protection.flags.Flags;
import com.sk89q.worldguard.protection.flags.StateFlag;
import com.sk89q.worldguard.protection.managers.RegionManager;
import com.sk89q.worldguard.protection.regions.ProtectedCuboidRegion;
import org.bukkit.*;
import org.bukkit.command.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.block.Action;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.event.player.PlayerInteractEvent;
import org.bukkit.inventory.*;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataType;
import java.util.*;

public final class PrivatCommand implements CommandExecutor,TabCompleter,Listener {
 private static final String MENU="§8Приваты",CREATE="§8Создать приват";
 private final PryanikPlugin plugin;private final NamespacedKey axeKey,createKey;private final Map<UUID,String> pending=new HashMap<>(),awaitingName=new HashMap<>(),awaitingMember=new HashMap<>();
 public PrivatCommand(PryanikPlugin plugin){this.plugin=plugin;axeKey=new NamespacedKey(plugin,"privat_selection_axe");createKey=new NamespacedKey(plugin,"privat_create_kind");}
 private ItemStack item(Material material,String name,String key,String value,String... lore){ItemStack item=new ItemStack(material);ItemMeta meta=item.getItemMeta();meta.setDisplayName(name);meta.setLore(Arrays.asList(lore));meta.getPersistentDataContainer().set(key.equals("axe")?axeKey:createKey,PersistentDataType.STRING,value);item.setItemMeta(meta);return item;}
 private void openMain(Player p){if(!plugin.gameModes().isModeWorld(p.getWorld())){p.sendMessage("§cМеню приватов доступно только в игровом грифе.");return;}String currentScope=plugin.clanScope(p);if(currentScope.startsWith("anarchy_")){p.sendMessage("§cВ анархии приваты отключены.");return;}Inventory inv=Bukkit.createInventory(null,27,MENU);inv.setItem(11,item(Material.CHEST,"§aСвой приват","create","personal","§7До 5 личных приватов в этом грифе"));try{if(plugin.db().clan(p.getUniqueId(),plugin.clanScope(p))!=null)inv.setItem(15,item(Material.BEACON,"§bПриват клана","create","clan","§7До 10 приватов на клан в этом грифе"));else inv.setItem(15,item(Material.GRAY_DYE,"§7Приват клана недоступен","create","clan","§7Сначала вступите в клан"));}catch(Exception ignored){}p.openInventory(inv);}
 private void openPersonalManagement(Player p){try{RegionManager m=WorldGuard.getInstance().getPlatform().getRegionContainer().get(BukkitAdapter.adapt(p.getWorld()));Inventory inv=Bukkit.createInventory(null,54,"§8Мои приваты");if(m!=null){int slot=0;for(var r:m.getRegions().values())if(r.getOwners().contains(p.getUniqueId())&&r.getId().contains("_p_")){if(slot>=45)break;inv.setItem(slot++,item(Material.CHEST,"§e"+r.getId(),"manage","personal","§7ЛКМ: добавить игрока","§7ПКМ: список/убрать игрока"));}}inv.setItem(49,item(Material.EMERALD,"§aДобавить игрока","manage","add","§7Сначала выберите приват из списка"));inv.setItem(50,item(Material.GOLDEN_AXE,"§6Создать приват","manage","create","§7Открыть меню создания и получить топор выделения"));p.openInventory(inv);}catch(Exception ex){p.sendMessage("§cНе удалось открыть список приватов.");}}
  private void openCreate(Player p,String kind){Inventory inv=Bukkit.createInventory(null,27,CREATE);inv.setItem(11,item(Material.GOLDEN_AXE,"§6Получить топор выделения","axe",kind,"§7ЛКМ — первая точка, ПКМ — вторая точка"));inv.setItem(15,item(Material.EMERALD_BLOCK,"§aСоздать приват","create",kind,"§7Сначала выделите область топором"));p.openInventory(inv);}
 @Override public boolean onCommand(CommandSender sender,Command command,String label,String[] args){if(!(sender instanceof Player p)){sender.sendMessage("Только игрок.");return true;}if(!plugin.authed(p.getUniqueId())){p.sendMessage("§cСначала войдите.");return true;}openMain(p);return true;}
 @EventHandler public void menuClick(InventoryClickEvent e){try{if(!(e.getWhoClicked() instanceof Player p))return;String title=e.getView().getTitle();if(!MENU.equals(title)&&!CREATE.equals(title)&&!title.equals("§8Мои приваты"))return;e.setCancelled(true);if(e.getRawSlot()<0||e.getRawSlot()>=e.getView().getTopInventory().getSize())return;if(!plugin.authed(p.getUniqueId())){p.closeInventory();return;}if(e.getRawSlot()>=e.getView().getTopInventory().getSize())return;ItemStack item=e.getCurrentItem();if(item==null||!item.hasItemMeta())return;String action=item.getItemMeta().getPersistentDataContainer().get(createKey,PersistentDataType.STRING);if("§8Мои приваты".equals(title)){if(e.getRawSlot()==50){openCreate(p,"personal");return;}if(e.getRawSlot()==49){p.sendMessage("§eВыберите свой приват в списке и нажмите по нему левой кнопкой, чтобы добавить игрока.");return;}String regionId=ChatColor.stripColor(item.getItemMeta().getDisplayName());if(regionId==null)return;var region=WorldGuard.getInstance().getPlatform().getRegionContainer().get(BukkitAdapter.adapt(p.getWorld())).getRegion(regionId);if(region==null||!region.getOwners().contains(p.getUniqueId()))return;if(e.isLeftClick()){awaitingMember.put(p.getUniqueId(),regionId);p.closeInventory();p.sendMessage("§eВведите ник игрока для добавления в этот приват. Для отмены: cancel.");}else{UUID target=region.getMembers().getUniqueIds().stream().findFirst().orElse(null);if(target!=null){region.getMembers().removePlayer(target);WorldGuard.getInstance().getPlatform().getRegionContainer().get(BukkitAdapter.adapt(p.getWorld())).save();p.sendMessage("§aИгрок удалён из привата.");}else p.sendMessage("§7В привате пока нет добавленных игроков.");}return;}String kind=action;if("§8Мои приваты".equals(title)){p.sendMessage("§eЧтобы получить топор: нажмите «Создать приват» в ячейке 51.");return;}if(MENU.equals(title)){if("personal".equals(kind)){p.closeInventory();openPersonalManagement(p);}else if("clan".equals(kind)){p.closeInventory();openCreate(p,kind);}return;}String axe=item.getItemMeta().getPersistentDataContainer().get(axeKey,PersistentDataType.STRING);if(axe!=null){ItemStack tool=item(Material.GOLDEN_AXE,"§6Топор выделения","axe",axe,"§7ЛКМ — точка 1; ПКМ — точка 2");p.getInventory().addItem(tool).values().forEach(left->p.getWorld().dropItemNaturally(p.getLocation(),left));p.sendMessage("§aТопор выделения выдан. Выделите две точки, затем снова нажмите «Создать приват».");pending.put(p.getUniqueId(),axe);p.closeInventory();return;}if(kind!=null){pending.put(p.getUniqueId(),kind);p.closeInventory();promptName(p,kind);}}catch(Exception ex){plugin.getLogger().warning("Privat GUI: "+ex.getMessage());}}
 private void promptName(Player p,String kind){pending.put(p.getUniqueId(),kind);awaitingName.put(p.getUniqueId(),kind);p.sendMessage("§eВведите в чат название привата: латиница, цифры, _ или -, до 20 символов. Для отмены напишите cancel.");}
  @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void chatMember(org.bukkit.event.player.AsyncPlayerChatEvent e){Player p=e.getPlayer();String regionId=awaitingMember.remove(p.getUniqueId());if(regionId==null||regionId.equals("*"))return;e.setCancelled(true);String name=e.getMessage().trim();if(name.equalsIgnoreCase("cancel")){p.sendMessage("§cДобавление отменено.");return;}if(!name.matches("[A-Za-z0-9_]{1,16}")){p.sendMessage("§cВведите корректный ник игрока (до 16 символов) или cancel.");awaitingMember.put(p.getUniqueId(),regionId);return;}Bukkit.getScheduler().runTask(plugin,()->{try{if(!plugin.authed(p.getUniqueId()))return;RegionManager m=WorldGuard.getInstance().getPlatform().getRegionContainer().get(BukkitAdapter.adapt(p.getWorld()));var r=m==null?null:m.getRegion(regionId);if(r==null||!r.getOwners().contains(p.getUniqueId())){p.sendMessage("§cПриват не найден или вы не его владелец.");return;}UUID target=plugin.db().uuidByNickname(name);if(target==null){p.sendMessage("§cИгрок с таким аккаунтом не найден.");return;}r.getMembers().addPlayer(target);m.save();p.sendMessage("§aИгрок добавлен в приват.");}catch(Exception ex){p.sendMessage("§cНе удалось добавить игрока.");plugin.getLogger().warning("Add private member: "+ex);}});}
  @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void chatName(org.bukkit.event.player.AsyncPlayerChatEvent e){Player p=e.getPlayer();String kind=awaitingName.remove(p.getUniqueId());if(kind==null)return;e.setCancelled(true);String name=e.getMessage().trim();if(name.equalsIgnoreCase("cancel")){pending.remove(p.getUniqueId());p.sendMessage("§cСоздание отменено.");return;}if(!name.matches("[A-Za-z0-9_-]{1,20}")){p.sendMessage("§cНазвание: латиница, цифры, _ или -, до 20 символов. Введите другое или cancel.");awaitingName.put(p.getUniqueId(),kind);return;}Bukkit.getScheduler().runTask(plugin,()->create(p,kind,name));}
  @EventHandler(priority=EventPriority.HIGH,ignoreCancelled=true) public void axeClick(PlayerInteractEvent e){Player p=e.getPlayer();ItemStack tool=e.getItem();if(tool==null||tool.getType()!=Material.GOLDEN_AXE||!tool.hasItemMeta())return;String kind=tool.getItemMeta().getPersistentDataContainer().get(axeKey,PersistentDataType.STRING);if(kind==null)return;e.setCancelled(true);if(!plugin.authed(p.getUniqueId()))return;WorldEditPlugin we=(WorldEditPlugin)Bukkit.getPluginManager().getPlugin("WorldEdit");if(we==null){p.sendMessage("§cWorldEdit не загружен.");return;}if(e.getAction()==Action.LEFT_CLICK_BLOCK){we.getSession(p).getRegionSelector(BukkitAdapter.adapt(p.getWorld())).selectPrimary(BukkitAdapter.asBlockVector(e.getClickedBlock().getLocation()),null);we.getSession(p).getRegionSelector(BukkitAdapter.adapt(p.getWorld())).learnChanges();p.sendMessage("§aТочка 1 выделена.");}else if(e.getAction()==Action.RIGHT_CLICK_BLOCK){we.getSession(p).getRegionSelector(BukkitAdapter.adapt(p.getWorld())).selectSecondary(BukkitAdapter.asBlockVector(e.getClickedBlock().getLocation()),null);we.getSession(p).getRegionSelector(BukkitAdapter.adapt(p.getWorld())).learnChanges();p.sendMessage("§aТочка 2 выделена. Выполните /privat и нажмите «Создать приват».");}}
 private void create(Player p,String kind,String name){String safeName=name.toLowerCase(Locale.ROOT);String scope=plugin.clanScope(p);if(scope.equals("legacy")||scope.startsWith("anarchy_")){p.sendMessage("§cПриваты здесь недоступны.");return;}try{RegionManager manager=WorldGuard.getInstance().getPlatform().getRegionContainer().get(BukkitAdapter.adapt(p.getWorld()));if(manager==null){p.sendMessage("§cМенеджер регионов недоступен.");return;}WorldEditPlugin we=(WorldEditPlugin)Bukkit.getPluginManager().getPlugin("WorldEdit");if(we==null){p.sendMessage("§cWorldEdit не загружен.");return;}Region selection;try{selection=we.getSession(p).getSelection(BukkitAdapter.adapt(p.getWorld()));}catch(IncompleteRegionException ex){selection=null;}if(selection==null){p.sendMessage("§cСначала выделите две точки выданным топором.");pending.put(p.getUniqueId(),kind);return;}if("personal".equals(kind)){String ownerPrefix=(scope+"_p_"+p.getUniqueId().toString().replace("-","")+"_");long count=manager.getRegions().values().stream().filter(r->r.getOwners().contains(p.getUniqueId())&&r.getId().startsWith(ownerPrefix)).count();if(count>=5){p.sendMessage("§cЛимит личных приватов — 5 на гриф.");return;}}else if("clan".equals(kind)){Clan clan=plugin.db().clan(p.getUniqueId(),scope);if(clan==null){p.sendMessage("§cЧтобы создать приват клана, вступите в клан.");return;}if(!clan.leader().equals(p.getUniqueId())){p.sendMessage("§cСоздавать приваты клана может только лидер.");return;}String prefix=("clan_"+scope+"_"+clan.name()+"_").toLowerCase(Locale.ROOT);long count=manager.getRegions().keySet().stream().filter(id->id.toLowerCase(Locale.ROOT).startsWith(prefix)).count();if(count>=10){p.sendMessage("§cЛимит клановых приватов — 10 на клан в этом грифе.");return;}}else return;String id;if("personal".equals(kind))id=(scope+"_p_"+p.getUniqueId().toString().replace("-","")+"_"+safeName).toLowerCase(Locale.ROOT);else{Clan clan=plugin.db().clan(p.getUniqueId(),scope);id=("clan_"+scope+"_"+clan.name()+"_"+safeName).toLowerCase(Locale.ROOT);}if(manager.hasRegion(id)){p.sendMessage("§cПриват с таким названием уже существует в этом грифе.");return;}ProtectedCuboidRegion region=new ProtectedCuboidRegion(id,selection.getMinimumPoint(),selection.getMaximumPoint());region.getOwners().addPlayer(p.getUniqueId());if("clan".equals(kind)){Clan clan=plugin.db().clan(p.getUniqueId(),scope);for(UUID member:plugin.db().clanMembers(clan.id(),scope))region.getMembers().addPlayer(member);}manager.addRegion(region);pending.remove(p.getUniqueId());pending.remove(p.getUniqueId());p.sendMessage("§aПриват «§e"+safeName+"§a» создан: §e"+id);}catch(Exception ex){plugin.getLogger().warning("Privat create: "+ex);p.sendMessage("§cНе удалось создать приват.");}}
 private boolean delete(Player p,String name){String scope=plugin.clanScope(p);if(scope.equals("legacy")||scope.startsWith("anarchy_")){p.sendMessage("§cПриваты здесь недоступны.");return true;}RegionManager manager=WorldGuard.getInstance().getPlatform().getRegionContainer().get(BukkitAdapter.adapt(p.getWorld()));if(manager==null)return true;String id=(scope+"_"+name).toLowerCase(Locale.ROOT);var region=manager.getRegion(id);if(region==null||!region.getOwners().contains(p.getUniqueId())){p.sendMessage("§cПриват не найден или вы не владелец.");return true;}manager.removeRegion(id);p.sendMessage("§aПриват удалён.");return true;}
 @Override public List<String> onTabComplete(CommandSender s,Command c,String alias,String[] args){return Collections.emptyList();}
}
